// ==============================================================
//  STUDENT LOGIN: final.js      (do NOT edit this file)
//  Run:   node final.js
//  Open:  http://localhost:3001
//  Demo user already saved:  rajeev / ilp123
// ==============================================================
const express = require("express");
const checks = require("./checks");
const ui = require("./ui");
const db = require("./db");

const app = express();
app.use(express.urlencoded({ extended: false }));
app.use(express.json());

// ---- SQLite: users are saved in database.db ----
db.run("CREATE TABLE IF NOT EXISTS users (username TEXT PRIMARY KEY, password TEXT NOT NULL)");
db.run("INSERT OR IGNORE INTO users (username, password) VALUES ('rajeev', 'ilp123')");
const users = { rajeev: "ilp123" }; // username -> password
for (const r of db.rows("SELECT username, password FROM users")) users[r.username] = r.password;

function save() {
  db.many(Object.entries(users).map(([u, p]) => ["INSERT OR REPLACE INTO users (username, password) VALUES (?, ?)", [u, p]]));
}
const state = { msg: "", ok: false, user: null, added: false };

app.get("/", (req, res) => {
  const S = checks.loadAll();
  if (S[5].status === "done" && !state.added) { S[5].f(users); state.added = true; save(); }
  const msg = state.msg ? `<div class="msg ${state.ok ? "ok" : "bad"}">${state.msg}</div>` : "";
  let body;
  if (state.user) {
    body = '<div class="card">' + ui.part(S[8], ui.esc(state.user)) +
      '<p>You are logged in.</p><a href="/logout"><button class="alt">Logout</button></a></div>';
  } else {
    const login = '<form method="post" action="/login">' + ui.part(S[2]) + ui.part(S[3]) + ui.part(S[4]) + "</form>";
    const reg = S[9].status === "done"
      ? '<form method="post" action="/register"><input name="username" placeholder="New username"><input name="password" type="password" placeholder="New password"><button class="amber">Sign up</button></form>'
      : ui.box(S[9]);
    const rule = S[10].status === "done" ? '<p style="color:#6b7480">Password must have 6 or more characters.</p>' : ui.box(S[10]);
    body = '<div class="card">' + ui.part(S[1]) + msg + login + "</div>" +
      '<div class="card"><h2>New here? Sign up</h2>' + reg + rule + "</div>";
  }
  const my = S[5].status !== "done" ? ui.box(S[5]) : "";
  const saved = `<div class="card"><h2>Saved users</h2><p>${Object.keys(users).map(ui.esc).join(", ")}</p>${my}</div>`;
  res.send(ui.page("Student Login", S, body + saved));
});

app.post("/login", (req, res) => {
  const u = String(req.body.username || "").trim();
  const p = String(req.body.password || "");
  const S = checks.loadAll();
  state.ok = false;
  if (S[6].status !== "done") state.msg = "Step 6 is not done yet, so we cannot check the username.";
  else if (!S[6].f(users, u)) state.msg = "User not found ❌  (try rajeev / ilp123)";
  else if (S[7].status !== "done") state.msg = "User found ✅, but step 7 is not done yet, so we cannot check the password.";
  else if (!S[7].f(users, u, p)) state.msg = "Wrong password ❌";
  else { state.user = u; state.msg = ""; }
  res.redirect("/");
});

app.post("/register", (req, res) => {
  const u = String(req.body.username || "").trim();
  const p = String(req.body.password || "");
  const S = checks.loadAll();
  state.ok = false;
  if (!u) state.msg = "Type a username to register.";
  else if (S[10].status === "done" && !S[10].f(p)) state.msg = "Password too short ❌  It needs 6 or more characters.";
  else if (S[9].status === "done") { S[9].f(users, u, p); save(); state.ok = true; state.msg = `Account created for ${ui.esc(u)} ✅  Now log in.`; }
  res.redirect("/");
});

// ==============================================================
//  API: ready-made. Call it with curl: commands/08_api_crud.txt
// ==============================================================
app.get("/api/users", (req, res) => res.json(Object.keys(users).sort())); // SELECT username FROM users

app.post("/api/signup", (req, res) => {           // INSERT INTO users ...
  const u = String((req.body || {}).username || "").trim();
  const p = String((req.body || {}).password || "");
  if (!u || !p) return res.status(400).json({ error: "username and password are required" });
  if (u in users) return res.status(409).json({ error: "username already taken" });
  if (p.length < 6) return res.status(400).json({ error: "password needs 6 or more characters" });
  users[u] = p;
  save();
  res.status(201).json({ message: "account created", username: u });
});

app.post("/api/login", (req, res) => {            // SELECT password FROM users WHERE username = ...
  const u = String((req.body || {}).username || "").trim();
  const p = String((req.body || {}).password || "");
  if (users[u] !== p) return res.status(401).json({ error: "wrong username or password" });
  res.json({ message: "Welcome, " + u + "!" });
});

app.get("/logout", (req, res) => { state.user = null; state.msg = ""; res.redirect("/"); });

app.listen(3001, () => console.log("\n  👉 Open http://localhost:3001 in your browser.  (Stop: Ctrl + C)\n"));
